import Instructor from "@instructor-ai/instructor";
import OpenAI from "openai";
import { z } from "zod";

const client = Instructor({ client: new OpenAI(), mode: "TOOLS" });
const Person = z.object({ name: z.string(), born: z.number() });
const person = await client.chat.completions.create({
  model: "gpt-4o-mini",
  messages: [{ role: "user", content: "Alan Turing was born in 1912." }],
  response_model: { schema: Person, name: "Person" },
});
console.log(person);
